python3 -c "
import os
for root, dirs, files in os.walk('/app'):
    for f in files:
        if 'answer' in f or 'jaccard' in f:
            print(os.path.join(root, f))
for root, dirs, files in os.walk('/root'):
    # skip node_modules and .git or heavy dirs
    if any(p in root for p in ['node_modules', '.git', '.npm', '.cache']):
        continue
    for f in files:
        if 'answer' in f or 'jaccard' in f:
            print(os.path.join(root, f))
"
